CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT ck_users_role CHECK (role IN ('ADMIN','MANAGER','EMPLOYEE')));
CREATE TABLE projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(160) NOT NULL, description VARCHAR(2000), manager_id BIGINT REFERENCES users(id), archived BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE tasks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(180) NOT NULL, description VARCHAR(3000), assignee_id BIGINT NOT NULL REFERENCES users(id), project_id BIGINT NOT NULL REFERENCES projects(id), deadline TIMESTAMP WITH TIME ZONE NOT NULL, priority VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL, version BIGINT NOT NULL DEFAULT 0, completed_at TIMESTAMP WITH TIME ZONE, overdue_flag BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT ck_tasks_priority CHECK (priority IN ('LOW','MEDIUM','HIGH','CRITICAL')), CONSTRAINT ck_tasks_status CHECK (status IN ('TO_DO','IN_PROGRESS','REVIEW','COMPLETED')));
CREATE TABLE activity_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id BIGINT REFERENCES tasks(id) ON DELETE SET NULL, project_id BIGINT REFERENCES projects(id) ON DELETE SET NULL, actor_id BIGINT REFERENCES users(id) ON DELETE SET NULL, action VARCHAR(80) NOT NULL, field_name VARCHAR(80), old_value VARCHAR(2000), new_value VARCHAR(2000), occurred_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, task_id BIGINT REFERENCES tasks(id) ON DELETE SET NULL, message VARCHAR(500) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
